/** Only this closed vocabulary crosses the server/client boundary. */
export const markdownTags = [
	"p",
	"h1",
	"h2",
	"h3",
	"h4",
	"h5",
	"h6",
	"blockquote",
	"ul",
	"ol",
	"li",
	"em",
	"strong",
	"s",
	"a",
	"code",
	"hr",
	"br",
	"table",
	"thead",
	"tbody",
	"tr",
	"th",
	"td",
] as const;
